// Filtre les avis parus depuis moins de 30 jours et les normalise en SIGNAL.
// Un signal est une PREUVE PUBLIQUE ET DATEE qu'une organisation investit dans
// Salesforce maintenant. Sans date ni URL verifiable, le signal ne compte pas.
const LIMITE_JOURS = 30;
const maintenant = new Date();
const sortie = [];

for (const item of $input.all()) {
  const res = item.json.results || [item.json];
  for (const r of res) {
    if (!r || !r.dateparution) continue;
    const parution = new Date(r.dateparution);
    const age = Math.floor((maintenant - parution) / 86400000);
    if (age > LIMITE_JOURS) continue;


    // Le BOAMP renvoie l'avis entier : un marche de traiteur peut contenir
    // "salesforce" dans une piece jointe. On exige la mention dans l'OBJET,
    // c'est-a-dire dans ce que l'acheteur achete reellement.
    const objet = (r.objet || '').toLowerCase();
    const pertinent = ['salesforce', 'sales cloud', 'service cloud', 'crm'].some(m => objet.includes(m));
    if (!pertinent) continue;

    const acheteur = (r.nomacheteur || '').trim();
    if (!acheteur) continue;

    sortie.push({ json: {
      signal_type: 'Appel offres public',
      signal_source: 'BOAMP',
      signal_url: 'https://www.boamp.fr/pages/avis/?q=idweb:"' + r.idweb + '"',
      signal_date: r.dateparution,
      signal_resume: (r.objet || '').slice(0, 400),
      entreprise: acheteur,
      echeance: r.datelimitereponse || null,
      reference: r.idweb,
      // Un marche public est le signal le plus fort qui soit : budget vote,
      // besoin decrit, calendrier connu. Bonus de fraicheur.
      score_signal: (objet.includes('salesforce') ? 9 : 7) - (age > 15 ? 1 : 0)
    }});
  }
}
return sortie;
